class Solution {
public:
    vector<bool> kidsWithCandies(vector<int>& candies, int extraCandies) {
        int most = *max_element(candies.begin(), candies.end());
        vector<bool> res;
        for (int i = 0; i < (int)candies.size(); i++) res.push_back(candies[i] + extraCandies >= most);
        return res;
    }
};
